// Open-Meteo devuelve arrays paralelos; las extracciones los aplanan a "v1,v2,…". Umbrales configurables en Variables.
const lista = (t) => String(t || '').split(',').map(s => s.trim()).filter(Boolean);
const dias = lista(vars.dias), tmax = lista(vars.tmax).map(Number), tmin = lista(vars.tmin).map(Number), lluvia = lista(vars.lluvia).map(Number);
if (!dias.length) return JSON.stringify({ error: 'sin datos: ejecuta el flow' });
const rojo = Number(vars.umbralRojo || 35), ambar = Number(vars.umbralAmbar || 30), agua = Number(vars.umbralLluvia || 5);
const nombre = (iso) => ['dom', 'lun', 'mar', 'mié', 'jue', 'vie', 'sáb'][new Date(iso + 'T12:00:00').getDay()];
const filas = dias.map((d, i) => ({ dia: d.slice(5).split('-').reverse().join('/'), nombre: nombre(d), tmax: tmax[i], tmin: tmin[i], lluvia: lluvia[i], calor: tmax[i] >= rojo ? '🔴' : tmax[i] >= ambar ? '🟡' : '🟢', cielo: lluvia[i] >= agua ? '☔' : lluvia[i] > 0 ? '🌦' : '☀️' }));
return JSON.stringify({ ciudad: vars.ciudad, filas, tmaxSemana: Math.max(...tmax), tminSemana: Math.min(...tmin), lluviaTotal: Math.round(lluvia.reduce((s, v) => s + v, 0) * 10) / 10, rojos: filas.filter(f => f.calor === '🔴').length, mojados: filas.filter(f => f.cielo === '☔').length, generado: new Date().toISOString() });

const e = JSON.parse(vars.semanaEstado || '{}'); if (e.error) return e.error;
const n = (v) => Number(v).toLocaleString('es-ES', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
return `${e.ciudad} · 7 días

` + e.filas.map(f => `${f.calor}${f.cielo} ${f.nombre} ${f.dia} · ${n(f.tmax)}° / ${n(f.tmin)}° · ${n(f.lluvia)} mm`).join('
') + `

Máx ${n(e.tmaxSemana)}° · mín ${n(e.tminSemana)}° · lluvia total ${n(e.lluviaTotal)} mm`;

const e = JSON.parse(vars.semanaEstado || '{}'); if (e.error) return '⏳ ' + e.error;
const avisos = [];
if (e.rojos) avisos.push(`🔴 ${e.rojos} día${e.rojos > 1 ? 's' : ''} con máxima ≥ ${vars.umbralRojo || 35} °C`);
if (e.mojados) avisos.push(`☔ lluvia ≥ ${vars.umbralLluvia || 5} mm en ${e.mojados} día${e.mojados > 1 ? 's' : ''} (${e.lluviaTotal} mm en total)`);
return avisos.length ? avisos.join('\n') : '✅ Semana tranquila: sin calor extremo ni lluvia destacable';

const e = JSON.parse(vars.semanaEstado || '{}');
if (e.error) return 'xychart-beta
  title "Sin datos: ejecuta el flow"
  x-axis ["-"]
  y-axis "°C" 0 --> 1
  bar [0]';
const lo = Math.min(...e.filas.map(f => f.tmin)), hi = Math.max(...e.filas.map(f => f.tmax));
return `xychart-beta
  title "${e.ciudad} · máxima (barras) y mínima (línea) · °C"
  x-axis [${e.filas.map(f => '"' + f.nombre + ' ' + f.dia + '"').join(', ')}]
  y-axis "°C" ${Math.floor(lo - 2)} --> ${Math.ceil(hi + 2)}
  bar [${e.filas.map(f => f.tmax).join(', ')}]
  line [${e.filas.map(f => f.tmin).join(', ')}]`;
